"""Backend selection for the vkernels Python bindings.

The public API in :mod:`vkernels.kernels`, :mod:`vkernels.comm` and
:mod:`vkernels.core` is backend-agnostic. Two backends implement it:

* **compiled** — the pybind11 extension :mod:`vkernels._core` (built from
  ``src/python/vkernels/_core.cpp`` by CMake when ``VKERNELS_BUILD_PYTHON=ON``).
  Every call crosses into the C++ library under ``src/c/vkernels/``; this is
  the fast path and the one that exercises the real kernels.
* **fallback** — a pure-Python (numpy) reference in :mod:`vkernels._fallback`
  that mirrors the CPU reference implementations, so the package stays
  importable and testable on machines where the extension was not built
  (mirroring the repository's "CPU reference always works" philosophy).

``load_extension()`` returns the compiled module when it can be found and
``None`` otherwise. Resolution order:

1. an already-importable ``vkernels._core`` (installed wheel copy or
   ``PYTHONPATH`` pointing at a build tree), then
2. a ``_core*.so`` sitting directly next to this file (wheel-installed
   extension that failed step 1 — e.g. ABI mismatch), then
3. a freshly built ``build/*/python/vkernels/_core*.so`` under the
   repository root (dev / editable-install CMake layout), newest first, then
4. ``None`` (the fallback backend is used).
"""

from __future__ import annotations

import importlib
import importlib.util
from pathlib import Path

_PKG_DIR = Path(__file__).resolve().parent

# Failure types a compiled-extension load can legitimately produce: ImportError
# for dlopen/dynamic-module problems (wrong interpreter, undefined symbols,
# missing PyInit), OSError for file-level issues, RuntimeError for in-module
# init checks (pybind11/numpy ABI-mismatch style). Anything else is a loader
# or module-init bug and must propagate instead of degrading to the fallback.
_EXTENSION_LOAD_ERRORS = (ImportError, OSError, RuntimeError)


def _repo_root() -> Path | None:
    """Repository root (a directory containing ``src/c/vkernels``), or None."""
    for candidate in (_PKG_DIR, *_PKG_DIR.parents):
        if (candidate / "src" / "c" / "vkernels").is_dir():
            return candidate
    return None


def _find_next_to_package() -> Path | None:
    """A ``_core*.so`` in the same directory as this file (wheel install)."""
    candidates = sorted(_PKG_DIR.glob("_core*.so"))
    if not candidates:
        return None
    return max(candidates, key=lambda p: p.stat().st_mtime)


def _find_built_extension() -> Path | None:
    """Newest ``build/*/python/vkernels/_core*.so`` under the repo root."""
    root = _repo_root()
    if root is None:
        return None
    candidates = sorted(root.glob("build/*/python/vkernels/_core*.so"))
    if not candidates:
        return None
    return max(candidates, key=lambda p: p.stat().st_mtime)


def _load_from_path(path: Path) -> object | None:
    """Try to load a .so from a filesystem path; return the module or None."""
    try:
        spec = importlib.util.spec_from_file_location("vkernels._core", path)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod
    except _EXTENSION_LOAD_ERRORS:
        return None


_loaded: object | None = None
_tried = False


def load_extension():
    """Import and return the compiled ``vkernels._core`` module, or None.

    The result is cached, so repeated calls are cheap. Failures (missing
    extension, ABI mismatch, numpy unavailable) degrade gracefully to None.
    """
    global _loaded, _tried
    if _tried:
        return _loaded
    _tried = True

    # 1. Already importable (installed wheel, or build dir on PYTHONPATH).
    try:
        _loaded = importlib.import_module("vkernels._core")
        return _loaded
    except _EXTENSION_LOAD_ERRORS:
        pass

    # 2. Next to this file (wheel-installed, but step 1 failed — e.g.
    #    the extension was built for a different Python or glibc).
    path = _find_next_to_package()
    if path is not None:
        _loaded = _load_from_path(path)
        if _loaded is not None:
            return _loaded

    # 3. Built by CMake into build/<preset>/python/vkernels/.
    path = _find_built_extension()
    if path is not None:
        _loaded = _load_from_path(path)
        return _loaded

    # 4. No compiled backend.
    _loaded = None
    return None


def backend_name() -> str:
    """``"compiled"`` when the extension is loaded, else ``"fallback"``."""
    return "compiled" if load_extension() is not None else "fallback"
"""The torch_ops calling convention: ops validate themselves.

Every public op in :mod:`vkernels.torch_ops` owns its full eligibility
check — device/arch, dtypes, shapes, contiguity, backend availability —
so callers never pre-gate on hardware or layout. The convention:

* **Contract miss -> ``OpNotEligible``.** The op cannot take the fused
  path for this input (CPU tensor, unexpected dtype, shape outside the
  validated envelope, missing Triton, ...). This is an *expected*,
  routine outcome: callers catch it and fall back to their eager torch
  path (or the op's ``*_reference`` oracle). ``OpNotEligible`` subclasses
  both :class:`ValueError` and :class:`TypeError`, so older call sites and
  tests that pinned either historical flavor keep working unchanged.
* **Anything else is a caller bug** (``TypeError`` for structurally wrong
  arguments that no fallback can fix, ``RuntimeError`` for operational
  failures such as an unconfigured tuned backend) and propagates.

This is what keeps model-side call sites to one line — ``if knob: return
op(...)`` — with the hardware/backend knowledge living here, next to the
kernels it describes (the deepseek_v41 arch already calls its ops exactly
this way).
"""

__all__ = ["OpNotEligible", "require", "same_gpu_contiguous"]


class OpNotEligible(ValueError, TypeError):
    """The fused kernel cannot run these inputs; the caller should fall back.

    Raised by the op's own validation for every routine miss — device/arch
    (CPU tensor on a CUDA kernel, HIP vs NVIDIA fp8 flavours), dtype,
    shape/contiguity outside the validated envelope, or a missing optional
    backend. Dual-inherits :class:`ValueError` and :class:`TypeError`
    because the contract historically escaped ops as either flavor and
    existing ``except`` clauses / tests pin both — every such site keeps
    working unchanged, while new call sites catch this exact class.
    """


def require(condition: bool, message: str) -> None:
    """Raise :class:`OpNotEligible` with ``message`` unless ``condition``."""
    if not condition:
        raise OpNotEligible(message)


def same_gpu_contiguous(*tensors) -> None:
    """Shared eligibility floor: CUDA-resident, one device, contiguous.

    The most common per-op validation prefix — reuse it instead of
    hand-rolling the loop in each launcher.
    """
    require(
        tensors[0].is_cuda,
        "inputs must be CUDA-resident on the same GPU "
        "(CPU callers take the *_reference/eager path)",
    )
    require(all(t.device == tensors[0].device for t in tensors),
            "inputs must share one GPU device")
    require(all(t.is_contiguous() for t in tensors),
            "inputs must be contiguous on the same GPU")
"""Shared fast-path gate for the torch ops that fall back to ``*_reference``.

The V4.1 ops own Triton accelerators but promise "always correct": instead of
raising off-GPU (the GLM set's contract) they route to their exact torch
reference. This helper keeps that availability probe — every tensor on CUDA,
triton importable — in one place; the op-specific shape gates (power-of-two
arange dims, small-tile cutoffs, scale-block shapes) stay next to their
kernels.

Importing this module loads no Torch and no Triton.
"""


def fast_path(*tensors) -> bool:
    """True when the Triton fast path may be taken: every tensor is on CUDA
    and triton importable. The caller still applies its own shape gates."""
    for t in tensors:
        if not t.is_cuda:
            return False
    try:
        import triton  # noqa: F401  (availability probe)
    except ImportError:
        # Triton genuinely absent -> no fast path. A *broken* triton install
        # (corrupt package) raises non-ImportError types, which now propagate
        # instead of being silently reported as "unavailable".
        return False
    return True
// vkernels/core/allocator.hpp
//
// The simplest possible host allocator: new/delete. Real training runs use
// pooled/arena allocators and (for GPU) cudaMallocAsync; this gives us a
// place to plug those in without churning call sites.
#pragma once

#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <new>

#include "vkernels/util/error.hpp"

namespace vkernels {

template <typename T>
T* allocate(std::size_t n) {
  VK_EXPECTS(n <= (SIZE_MAX / sizeof(T)), "allocation size overflow");
  if (n == 0) return nullptr;
  void* p = std::malloc(n * sizeof(T));
  if (p == nullptr) throw std::bad_alloc();
  return static_cast<T*>(p);
}

template <typename T>
void deallocate(T* p) noexcept {
  std::free(p);
}

// Owning contiguous buffer. Trivial on purpose; replace with a real
// allocator (host pooled / cudaMalloc) without changing call sites.
template <typename T>
class Buffer {
 public:
  Buffer() = default;
  explicit Buffer(std::size_t n) : data_(allocate<T>(n)), size_(n) {}

  ~Buffer() { deallocate(data_); }

  Buffer(const Buffer&) = delete;
  Buffer& operator=(const Buffer&) = delete;

  Buffer(Buffer&& other) noexcept : data_(other.data_), size_(other.size_) {
    other.data_ = nullptr;
    other.size_ = 0;
  }

  Buffer& operator=(Buffer&& other) noexcept {
    if (this != &other) {
      deallocate(data_);
      data_ = other.data_;
      size_ = other.size_;
      other.data_ = nullptr;
      other.size_ = 0;
    }
    return *this;
  }

  T* data() { return data_; }
  const T* data() const { return data_; }
  std::size_t size() const { return size_; }
  T& operator[](std::size_t i) {
    VK_EXPECTS(i < size_, "buffer index out of range");
    return data_[i];
  }
  const T& operator[](std::size_t i) const {
    VK_EXPECTS(i < size_, "buffer index out of range");
    return data_[i];
  }

 private:
  T* data_ = nullptr;
  std::size_t size_ = 0;
};

}  // namespace vkernels
// vkernels/core/stream.cpp — host implementation of vkernels::Stream.
#include "vkernels/core/stream.hpp"

#include <condition_variable>
#include <deque>
#include <mutex>
#include <thread>

namespace vkernels {

struct Stream::Impl {
  std::deque<std::function<void()>> queue;
  mutable std::mutex m;
  std::condition_variable work_cv;   // signalled when a task is enqueued
  std::condition_variable done_cv;   // signalled when outstanding hits zero
  std::size_t outstanding = 0;
  std::size_t total = 0;
  bool stop = false;
  std::thread worker;

  Impl() : worker([this] { loop(); }) {}

  ~Impl() {
    {
      std::lock_guard<std::mutex> lk(m);
      stop = true;
    }
    work_cv.notify_one();
    if (worker.joinable()) worker.join();
  }

  void loop() {
    for (;;) {
      std::function<void()> task;
      {
        std::unique_lock<std::mutex> lk(m);
        work_cv.wait(lk, [this] { return stop || !queue.empty(); });
        if (stop && queue.empty()) return;
        task = std::move(queue.front());
        queue.pop_front();
      }
      {
        task();  // may acquire/release the GIL via wrapped callables
      }          // task destroyed here, BEFORE the completion signal
      {
        std::lock_guard<std::mutex> lk(m);
        if (--outstanding == 0) done_cv.notify_all();
      }
    }
  }
};

Stream::Stream() : impl_(new Impl()) {}

Stream::~Stream() { delete impl_; }

Stream::Stream(Stream&& other) noexcept : impl_(other.impl_) { other.impl_ = nullptr; }

Stream& Stream::operator=(Stream&& other) noexcept {
  if (this != &other) {
    delete impl_;
    impl_ = other.impl_;
    other.impl_ = nullptr;
  }
  return *this;
}

void Stream::submit(std::function<void()> task) {
  std::lock_guard<std::mutex> lk(impl_->m);
  impl_->queue.push_back(std::move(task));
  ++impl_->outstanding;
  ++impl_->total;
  impl_->work_cv.notify_one();
}

void Stream::wait() {
  std::unique_lock<std::mutex> lk(impl_->m);
  impl_->done_cv.wait(lk, [this] { return impl_->outstanding == 0; });
}

std::size_t Stream::submitted() const { return impl_->total; }

}  // namespace vkernels

