//! Device and stream abstractions (src/c/vkernels/core).
//!
//! On the host build every "device" is the CPU and a no-op; under CUDA
//! `Device` records the cuda device and offers `set_current`/`sync`.
//! `Stream` is an ordered, asynchronous queue of tasks backed by one worker
//! thread per stream — the host model of a CUDA stream: tasks within a
//! stream run in submission order, distinct streams run concurrently.

use std::os::raw::{c_int, c_void};

use crate::{from_status, sys, Error};

/// A compute device. `index == -1` selects the default device (CPU on a
/// host build, device 0 under CUDA).
#[derive(Debug)]
pub struct Device {
    raw: *mut sys::vk_device,
}

// `Device` is a thin wrapper over an index; the CUDA-level operations act on
// process-global state exactly as in C++.
unsafe impl Send for Device {}
unsafe impl Sync for Device {}

impl Device {
    /// Create a device handle; `index == -1` means "default".
    ///
    /// # Panics
    /// Only when the C++ side cannot allocate the handle (out of memory).
    pub fn new(index: i32) -> Self {
        let raw = unsafe { sys::vk_device_new(index as c_int) };
        assert!(
            !raw.is_null(),
            "vk_device_new failed: {}",
            sys::last_error()
        );
        Device { raw }
    }

    /// The device index (`-1` = default).
    pub fn index(&self) -> i32 {
        (unsafe { sys::vk_device_index(self.raw) }) as i32
    }

    /// Make this device current (no-op on the CPU host build).
    pub fn set_current(&self) -> Result<(), Error> {
        from_status(unsafe { sys::vk_device_set_current(self.raw) })
    }

    /// Block until this device has finished all work (no-op on host).
    pub fn sync(&self) -> Result<(), Error> {
        from_status(unsafe { sys::vk_device_sync(self.raw) })
    }

    /// True if this device can access `other` directly (false on host).
    pub fn supports_peer(&self, other: &Device) -> bool {
        unsafe { sys::vk_device_supports_peer(self.raw, other.raw) != 0 }
    }
}

impl PartialEq for Device {
    fn eq(&self, other: &Self) -> bool {
        unsafe { sys::vk_device_eq(self.raw, other.raw) != 0 }
    }
}

impl Eq for Device {}

impl Drop for Device {
    fn drop(&mut self) {
        unsafe { sys::vk_device_delete(self.raw) }
    }
}

/// The default [`Device`] (`index == -1`).
pub fn default_device() -> Device {
    Device::new(-1)
}

/// An ordered, asynchronous queue of tasks (the host worker-thread model of
/// a CUDA stream).
///
/// Tasks within a stream run in submission order; distinct streams run
/// concurrently. Dropping the stream first runs every still-queued task
/// (the C++ destructor joins the worker thread).
#[derive(Debug)]
pub struct Stream {
    pub(crate) raw: *mut sys::vk_stream,
}

// The C++ Stream is mutex-protected, so submit/wait from several threads is
// safe; sharing it across threads mirrors that contract.
unsafe impl Send for Stream {}
unsafe impl Sync for Stream {}

impl Stream {
    /// Create a new stream with one worker thread.
    ///
    /// # Panics
    /// Only when the C++ side cannot allocate the handle (out of memory).
    pub fn new() -> Self {
        let raw = unsafe { sys::vk_stream_new() };
        assert!(
            !raw.is_null(),
            "vk_stream_new failed: {}",
            sys::last_error()
        );
        Stream { raw }
    }

    /// Enqueue `task` to run on this stream, in submission order. The task
    /// runs on the stream's worker thread and must therefore be `Send`.
    ///
    /// A panic inside `task` is caught and does not abort the process; the
    /// stream keeps processing later tasks.
    pub fn submit<F>(&self, task: F) -> Result<(), Error>
    where
        F: FnOnce() + Send + 'static,
    {
        let boxed: Box<dyn FnOnce() + Send> = Box::new(task);
        // Double box: `Box::into_raw` on a Box<dyn Fn> returns the closure
        // data pointer, which is a *dangling* pointer (0x1) for zero-sized
        // closures. The outer Box is always a real allocation, so `ctx` is
        // always a valid address for the trampoline to dereference.
        let outer: Box<Box<dyn FnOnce() + Send>> = Box::new(boxed);
        let ctx = Box::into_raw(outer) as *mut c_void;
        let code = unsafe { sys::vk_stream_submit(self.raw, Some(task_trampoline), ctx) };
        if code != sys::VK_OK {
            // The C++ side never stored the callback (submission failed
            // before enqueueing), so the box is still ours to reclaim.
            let slot: Box<Box<dyn FnOnce() + Send>> =
                unsafe { Box::from_raw(ctx as *mut Box<dyn FnOnce() + Send>) };
            drop(slot);
            return Err(crate::from_code(code));
        }
        Ok(())
    }

    /// Block the calling thread until every task submitted so far has run.
    pub fn wait(&self) {
        unsafe { sys::vk_stream_wait(self.raw) }
    }

    /// Number of tasks submitted so far (completed + queued).
    pub fn submitted(&self) -> usize {
        unsafe { sys::vk_stream_submitted(self.raw) }
    }
}

impl Default for Stream {
    fn default() -> Self {
        Stream::new()
    }
}

impl Drop for Stream {
    fn drop(&mut self) {
        // The C++ destructor joins the worker thread, draining the queue
        // (and with it the task boxes, freed by the trampoline).
        unsafe { sys::vk_stream_delete(self.raw) }
    }
}

unsafe extern "C" fn task_trampoline(ctx: *mut c_void) {
    let outer: Box<Box<dyn FnOnce() + Send>> =
        unsafe { Box::from_raw(ctx as *mut Box<dyn FnOnce() + Send>) };
    let task = *outer; // move the inner box out; drop the (ZST-safe) slot
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(task));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn device_basics() {
        let d = Device::new(-1);
        assert_eq!(d.index(), -1);
        assert_eq!(Device::new(3).index(), 3);
        assert_eq!(Device::new(0), Device::new(0));
        assert_ne!(Device::new(0), Device::new(1));
        assert_eq!(default_device(), Device::new(-1));
    }

    #[test]
    fn host_device_operations_are_noops() {
        let d = Device::new(0);
        d.set_current().unwrap();
        d.sync().unwrap();
        assert!(!d.supports_peer(&Device::new(1))); // host build
    }

    #[test]
    fn stream_runs_in_order() {
        let s = Stream::new();
        let log = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        for i in 0..50 {
            let log = log.clone();
            s.submit(move || log.lock().unwrap().push(i)).unwrap();
        }
        s.wait();
        assert_eq!(*log.lock().unwrap(), (0..50).collect::<Vec<_>>());
    }

    #[test]
    fn stream_submitted_counts() {
        let s = Stream::new();
        assert_eq!(s.submitted(), 0);
        s.submit(|| {}).unwrap();
        s.submit(|| {}).unwrap();
        s.wait();
        assert_eq!(s.submitted(), 2);
    }

    #[test]
    fn distinct_streams_run_concurrently() {
        let a = Stream::new();
        let b = Stream::new();
        let order = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        {
            let order = order.clone();
            a.submit(move || {
                std::thread::sleep(std::time::Duration::from_millis(50));
                order.lock().unwrap().push("a");
            })
            .unwrap();
        }
        b.submit({
            let order = order.clone();
            move || order.lock().unwrap().push("b")
        })
        .unwrap();
        a.wait();
        b.wait();
        // "b" finishes before "a" (a sleeps), proving concurrent execution.
        assert_eq!(*order.lock().unwrap(), ["b", "a"]);
    }
}
//! Build script for vkernels-sys.
//!
//! Builds the vkernels C++ static library from the repository root with the
//! `cmake` crate — reusing the project's own CMakeLists as the single source
//! of truth for the source list and feature flags — and links it into this
//! crate together with the C ABI from src/c/vkernels/capi/capi.cpp (which is
//! part of the same static library).
//!
//! Feature flags passed to CMake:
//!   * tests / benchmarks / python / rust sub-builds are disabled (this build
//!     only needs the `vkernels` library target),
//!   * `VKERNELS_BUILD_CUDA` defaults to OFF (host / CPU-reference build, no
//!     toolkit required); set the `VKERNELS_RUST_CUDA` environment variable
//!     to `ON`/`1` to compile the CUDA kernels too. When CUDA is enabled the
//!     CUDA runtime is linked from the toolkit found by CMake (the
//!     `VKERNELS_CUDA_ROOT` env var or `/usr/local/cuda`).
//!
//! With the `external-c-abi` Cargo feature, skip the bundled host build and
//! link a prebuilt `libvkernels_c.so` from `VKERNELS_LIB_DIR`. The legacy
//! `KVAAS_VKERNELS_LIB_DIR` name remains a temporary migration alias.

use std::env;
use std::path::{Path, PathBuf};
use std::process::Command;

fn main() {
    if env::var_os("CARGO_FEATURE_EXTERNAL_C_ABI").is_some() {
        link_external_c_abi();
        return;
    }

    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    // src/rust/vkernels-sys -> repository root.
    let repo_root = manifest_dir
        .parent()
        .unwrap()
        .parent()
        .unwrap()
        .parent()
        .unwrap();

    let cuda_requested = env::var("VKERNELS_RUST_CUDA")
        .map(|v| v == "1" || v.eq_ignore_ascii_case("on") || v.eq_ignore_ascii_case("true"))
        .unwrap_or(false);

    // nvcc is not on the PATH in this environment; a host build is always the
    // default, exactly like the `host` CMake preset.
    if cuda_requested && which("nvcc").is_none() {
        panic!(
            "VKERNELS_RUST_CUDA=ON requires nvcc on PATH; \
             the vkernels CMake build would fall back to the host path otherwise"
        );
    }

    let mut config = cmake::Config::new(repo_root);
    config
        .define("VKERNELS_BUILD_TESTS", "OFF")
        .define("VKERNELS_BUILD_BENCHMARKS", "OFF")
        .define("VKERNELS_BUILD_PYTHON", "OFF")
        .define("VKERNELS_BUILD_RUST", "OFF")
        .define(
            "VKERNELS_BUILD_CUDA",
            if cuda_requested { "ON" } else { "OFF" },
        )
        .profile("Release")
        // The project has no `install` rule; build the default (all) target
        // in place. The archive then lives in <out>/build/libvkernels.a.
        .no_build_target(true);
    // The vkernels library is built with -Werror; keep it that way so a
    // broken C ABI shim fails the Rust build too.
    let dst = config.build();
    // add_subdirectory(src/c) places the archive in <build>/src/c for the
    // Makefiles and Ninja generators; advertise both candidates.
    let build_dir = dst.join("build");
    println!(
        "cargo:rustc-link-search=native={}",
        build_dir.join("src").join("c").display()
    );
    println!("cargo:rustc-link-search=native={}", build_dir.display());
    println!("cargo:rustc-link-lib=static=vkernels");

    // Sanity check: the C ABI (src/c/vkernels/capi/capi.cpp) must be compiled
    // into the library. If the archive does not export it, the Rust bindings
    // cannot link and the build would fail later with confusing undefined-
    // symbol errors — fail here with a clear message instead.
    verify_capi_symbols(&build_dir);

    // Threads::Threads (used by Stream / BlockingQueue / OverlapExecutor).
    if env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("macos")
        && env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows")
    {
        println!("cargo:rustc-link-lib=pthread");
    }

    // The C++ static library pulls in the C++ standard library; rustc does
    // not link it by default, so declare it explicitly. libstdc++ on the
    // GNU toolchains, libc++ on macOS, nothing extra on MSVC (the MSVC
    // headers' #pragma comment(lib) handles it).
    let target_os = env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let target_env = env::var("CARGO_CFG_TARGET_ENV").unwrap_or_default();
    if target_os == "macos" {
        println!("cargo:rustc-link-lib=dylib=c++");
    } else if target_env != "msvc" {
        println!("cargo:rustc-link-lib=dylib=stdc++");
    }

    if cuda_requested {
        link_cuda_runtime();
    }

    // Rebuild when the C++ sources or the C ABI change.
    println!(
        "cargo:rerun-if-changed={}",
        repo_root.join("src").join("c").display()
    );
    println!(
        "cargo:rerun-if-changed={}",
        repo_root.join("CMakeLists.txt").display()
    );
    println!("cargo:REDACTED");
}

fn link_external_c_abi() {
    println!("cargo:rerun-if-env-changed=VKERNELS_LIB_DIR");
    println!("cargo:REDACTED");
    if let Some(directory) =
        env::var_os("VKERNELS_LIB_DIR").or_else(|| env::var_os("KVAAS_VKERNELS_LIB_DIR"))
    {
        println!(
            "cargo:rustc-link-search=native={}",
            PathBuf::from(directory).display()
        );
    }
    println!("cargo:rustc-link-lib=dylib=vkernels_c");
}

/// The vkernels static library is CUDA-enabled but the CUDA runtime is a
/// transitive dependency of a static archive, so this crate must link it
/// itself. Best effort: derive the toolkit root from VKERNELS_CUDA_ROOT,
/// CUDA_PATH or the conventional /usr/local/cuda location.
fn link_cuda_runtime() {
    let root = env::var("VKERNELS_CUDA_ROOT")
        .or_else(|_| env::var("CUDA_PATH"))
        .unwrap_or_else(|_| "/usr/local/cuda".to_string());
    let root = Path::new(&root);

    for lib_dir in ["lib64", "lib"] {
        let dir = root.join(lib_dir);
        if dir.is_dir() {
            println!("cargo:rustc-link-search=native={}", dir.display());
        }
    }
    println!("cargo:rustc-link-lib=dylib=cudart");
    println!("cargo:rustc-link-lib=dylib=cuda");
}

fn which(prog: &str) -> Option<PathBuf> {
    let path = env::var_os("PATH")?;
    for dir in env::split_paths(&path) {
        let candidate = dir.join(prog);
        if candidate.is_file() {
            return Some(candidate);
        }
    }
    None
}

/// Assert that the built static library exports the C ABI entry points.
fn verify_capi_symbols(build_dir: &Path) {
    let archive = build_dir.join("src").join("c").join("libvkernels.a");
    let fallback = build_dir.join("libvkernels.a");
    let archive = if archive.is_file() { archive } else { fallback };
    if !archive.is_file() {
        panic!("vkernels static library not found at {}", archive.display());
    }
    let output = Command::new("nm")
        .arg(&archive)
        .output()
        .expect("failed to run `nm` to verify the vkernels archive");
    let symbols = String::from_utf8_lossy(&output.stdout);
    if !symbols.lines().any(|l| l.contains(" T vk_version")) {
        panic!(
            "the built libvkernels.a does not export the C ABI (vk_version); \
             make sure src/c/CMakeLists.txt compiles src/c/vkernels/capi/capi.cpp"
        );
    }
}
// vkernels/comm/overlap.cpp
#include "vkernels/comm/overlap.hpp"

#include <future>
#include <memory>
#include <vector>

namespace vkernels::comm {

OverlapExecutor::Result OverlapExecutor::run(std::size_t iters,
                                             std::function<int(std::size_t)> compute,
                                             std::function<void(std::size_t, int)> comm) {
  std::vector<std::shared_future<int>> ready;
  ready.resize(iters);

  for (std::size_t i = 0; i < iters; ++i) {
    auto promise = std::make_shared<std::promise<int>>();
    ready[i] = promise->get_future().share();

    // Submit compute(i) on the compute stream; it fulfils the promise.
    // Note: `compute`/`comm` are captured BY REFERENCE. Copying a
    // pybind11-wrapped std::function (func_handle) needs the GIL, and the
    // caller may have released it while we block below; the reference is
    // safe because run() waits for every task before returning.
    compute_.submit([&compute, i, promise]() {
      int v = compute(i);
      promise->set_value(v);
    });

    // Submit comm(i) on the comm stream; it blocks on the future (honouring the
    // data dependency) while the compute stream is free to start compute(i+1).
    auto fut = ready[i];
    comm_.submit([&comm, i, fut]() {
      int v = fut.get();
      comm(i, v);
    });
  }

  compute_.wait();
  comm_.wait();

  return Result{iters, iters};
}

}  // namespace vkernels::comm
// vkernels/comm/channel.cpp
#include "vkernels/comm/channel.hpp"

#include <utility>

namespace vkernels::comm {

std::vector<std::unique_ptr<Channel>> make_ring_channels(int world) {
  VK_EXPECTS(world > 0, "world must be positive");
  // One queue per directed edge: edge[r] carries rank r -> rank (r+1)%world.
  std::vector<std::shared_ptr<BlockingQueue>> edges;
  edges.reserve(static_cast<std::size_t>(world));
  for (int r = 0; r < world; ++r) edges.push_back(std::make_shared<BlockingQueue>());

  std::vector<std::unique_ptr<Channel>> channels;
  channels.reserve(static_cast<std::size_t>(world));
  for (int r = 0; r < world; ++r) {
    int out_idx = r;            // r -> (r+1)%world
    int in_idx = (r - 1 + world) % world;  // (r-1)%world -> r
    channels.push_back(std::make_unique<MockChannel>(edges[out_idx], edges[in_idx]));
  }
  return channels;
}

}  // namespace vkernels::comm

