#include "vkernels/comm/overlap.hpp"

#include <future>
#include <memory>
#include <vector>

namespace vkernels::comm {

OverlapExecutor::Result OverlapExecutor::run(std::size_t iters,
                                             std::function<int(std::size_t)> compute,
                                             std::function<void(std::size_t, int)> comm) {
  std::vector<std::shared_future<int>> ready;
  ready.resize(iters);

  for (std::size_t i = 0; i < iters; ++i) {
    auto promise = std::make_shared<std::promise<int>>();
    ready[i] = promise->get_future().share();

    // Submit compute(i) on the compute stream; it fulfils the promise.
    // Note: `compute`/`comm` are captured BY REFERENCE. Copying a
    // pybind11-wrapped std::function (func_handle) needs the GIL, and the
    // caller may have released it while we block below; the reference is
    // safe because run() waits for every task before returning.
    compute_.submit([&compute, i, promise]() {
      int v = compute(i);
      promise->set_value(v);
    });

    // Submit comm(i) on the comm stream; it blocks on the future (honouring the
    // data dependency) while the compute stream is free to start compute(i+1).
    auto fut = ready[i];
    comm_.submit([&comm, i, fut]() {
      int v = fut.get();
      comm(i, v);
    });
  }

  compute_.wait();
  comm_.wait();

  return Result{iters, iters};
}

}  // namespace vkernels::comm
# .github/workflows/ci.yml — host + CUDA CI
#
# Runs on every push and PR.  The host job compiles and tests the full
# C++ library with 100% line-coverage enforcement.  The CUDA job runs
# only on self-hosted runners tagged `cuda`.
name: CI

on:
  push:
    branches: [main, develop]
  pull_request:
    branches: [main]
  workflow_dispatch:

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: true

jobs:
  # ------------------------------------------------------------------
  # Host build + test + coverage (no GPU required)
  # ------------------------------------------------------------------
  host:
    runs-on: ubuntu-24.04
    steps:
      - uses: actions/checkout@v4

      - uses: jdx/mise-action@v2
        with:
          install: true

      - name: Lint (ruff, pyflakes)
        run: uvx ruff check src/python tests/python

      - name: Configure (coverage)
        run: cmake --preset coverage

      - name: Build
        run: cmake --build --preset coverage -j$(nproc)

      - name: Test
        run: ctest --preset coverage --output-on-failure -j$(nproc)

      - name: Coverage gate (100 %)
        run: >
          python3 meta/scripts/coverage.py
          --build-dir build/coverage
          --source-dir src/c
          --min 100

      - name: Python smoke tests (fallback backend)
        run: |
          uv run vkl list
          uv run vkl info gemm
          uv run python -m pytest tests/python/ -v

  # ------------------------------------------------------------------
  # CUDA build + test (needs self-hosted runner with toolkit + GPU)
  # ------------------------------------------------------------------
  cuda:
    # Self-hosted on the ds6 runner (labels self-hosted,cuda). Runs inside
    # the runner-local `vkernels-ci:cuda13` image (CUDA 13.0 toolkit +
    # cmake + git + python3-dev + upgraded setuptools) with the host NVIDIA
