// Most recent error message on the calling thread; valid until the next
// failing call on the same thread. Internal linkage — the only access is
// through the accessors below (also used by the VK_CAPI_CATCH macros).
static thread_local std::string g_last_error;

// Status code of the most recent failing call (VK_OK when none).
static thread_local int g_last_error_code = VK_OK;

void set_last_error(int code, const char* message) {
  g_last_error_code = code;
  g_last_error = (message != nullptr) ? std::string(message) : std::string();
}

const char* last_error() { return g_last_error.c_str(); }

int last_error_code() { return g_last_error_code; }

