    pub src_stride: usize,
    /// Byte offset of the tile's first row in the destination.
    pub dst_offset: usize,
    /// Bytes between destination rows (>= width).
    pub dst_stride: usize,
    /// Bytes copied per row.
    pub width: usize,
    /// Number of rows copied.
    pub height: usize,
}

