    s.part_out = no;  // previous generation intentionally abandoned
    s.part_lse = nl;
    s.cap_out = n_out;
    s.cap_lse = n_lse;
  }
  *p_out = s.part_out;
  *p_lse = s.part_lse;
  return true;
}
