#   mise run configure         cmake configure (P=host by default)
#   mise run build             cmake build
#   mise run test              run all tests (C++ + Python)
#   mise run configure-cuda    cmake configure (CUDA)
#   mise run build-cuda        cmake build (CUDA)
#   mise run configure-hip     cmake configure (HIP/ROCm, gfx942)
#   mise run build-hip         cmake build (HIP)
#   mise run build-wheel       package a host wheel
#   mise run build-wheel-cuda  package a CUDA wheel
#   mise run build-wheel-hip   package an AMD ROCm wheel
#   mise run py-sync           uv sync -> .venv/
#   mise run fmt               clang-format check
#
# CUDA & HIP toolkits are typically installed at the system level
# (see CMakePresets.json); they are not pinned here.

[tools]
python = "3.12"              # pyproject.toml requires >=3.9; uv manages .venv/
uv = "latest"                # Python package manager (see pyproject.toml)
cmake = "latest"             # build system (CMakeLists.txt requires >=3.18)
rust = "latest"              # optional: src/rust/ bindings (edition 2021)
clang-format = "latest"      # also provides clang-tidy (from LLVM via asdf)
ccache = "latest"            # optional: faster C++ recompilation
ninja = "latest"             # optional: alternative CMake generator

[env]
# Tell uv to target the repository-local virtualenv.
UV_PROJECT_ENVIRONMENT = ".venv"

[tasks]
# ---- C/C++ build (mirrors Makefile) ----
# The P env var selects the CMake preset: host, debug, coverage, asan,
# cuda, hip, python, hip-python, etc.  Shortcut tasks below set P for
# convenience (e.g. `mise run build-hip` instead of `P=hip mise run build`).
configure = "cmake --preset ${P:-host}"
build = "cmake --build --preset ${P:-host}"
test = "cmake --build --preset ${P:-host} --target test"
clean = "rm -rf build/${P:-host}"

# ---- Toolchain shortcuts (CUDA / HIP) ----
# C++ library only  (cuda → build/cuda,  hip → build/hip)
configure-cuda = "cmake --preset cuda"
"}

