    HIP launches target the CURRENT device: without this guard, tensors
    living on a non-current GPU (multi-GPU serving) launch on the wrong
    device with foreign pointers — garbage or a fault (#69 non-current
    device contract). No-op when t is already on the current device;
    restores the previous device on exit. torch.cuda.device requires a
    torch Tensor (device index), which every caller here has.
    """
    import contextlib
    return contextlib.nullcontext() if t is None else torch.cuda.device(t.device)


def _launch(f_stream, f_legacy, args, stream):
    """Call the _stream symbol when present (returning the launch error so a
    partial failure is never silent); fall back to the legacy symbol for
    pre-#69 libraries (stream must be None there)."""
    if f_stream is not None:
        rc = f_stream(*args, _stream_ptr(stream))
        if rc != 0:
            raise RuntimeError(f"HIP launch failed: error {rc}")
        return
    if stream is not None:
        raise RuntimeError("this libvkernels_hip build predates the #69 "
                           "stream ABI; pass stream=None or rebuild")
    f_legacy(*args)


def _sym(lib, name):
    return getattr(lib, name, None)


def stream_abi() -> bool:
    """True when the loaded library carries the #69 ``*_stream`` symbols
    (graph-capture-safe launches). Floe uses this to decide whether its
    device dispatch may run under capture or must fall back to torch."""
    lib = _load()
    if lib is None:
        return False
    return hasattr(lib, "vk_hip_kda_delta_rule_fwd_chunked_with_scratch_stream")


def available() -> bool:
    """True when ``libvkernels_hip.so`` is loadable (device path usable)."""
    return _load() is not None


def _dptr(t: torch.Tensor) -> int:
    return t.data_ptr()


def _check_device(t: torch.Tensor, name: str) -> None:
    if not t.is_cuda:
        raise ValueError(f"{name} must be a device tensor (got {t.device})")
    if torch.cuda.is_current_stream_capturing() and not stream_abi():
        # Pre-#69 library: the launches would go to the legacy default
        # stream, which cannot be captured. With the stream ABI the calls
        # resolve torch's CURRENT (capturing) stream and are safe.
        raise RuntimeError(
            "this libvkernels_hip build predates the #69 stream ABI; its "
            "launches go to the legacy default stream and cannot be "
            "captured into a CUDA/HIP graph"
        )


def _contig(t: torch.Tensor, name: str, dtype: torch.dtype) -> torch.Tensor:
    _check_device(t, name)
    if t.dtype != dtype:
        raise ValueError(f"{name} must be {dtype} (got {t.dtype})")
"""vkl — list and inspect the kernels implemented in the vkernels repository,
and drive their persistent tuning.

Usage (from the repo):

    python3 -m vkernels.cli list            # list kernels + comm primitives
    python3 -m vkernels.cli info gemm       # details for one entry
    python3 -m vkernels.cli tune status     # what is tuned, both tiers
    python3 -m vkernels.cli tune run --all  # sweep + persist winners
    python3 -m vkernels.cli --version

``pip install -e ./src`` installs a ``vkl`` console script with the same
behaviour. The repository root is auto-detected (override with ``--root`` or
the ``VKERNELS_ROOT`` environment variable).
"""

from __future__ import annotations

import argparse
import difflib
import json
import sys
from pathlib import Path

from vkernels import discovery

_DESC_WIDTH = 72


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        prog="vkl",
        description="List and inspect the kernels implemented in the "
                    "vkernels repository (src/c/vkernels).",
    )
    p.add_argument("--version", action="version",
                   version=f"vkl {discovery.version()}")
    p.add_argument("--root", metavar="DIR", default=None,
                   help="vkernels repository root (default: auto-detected)")
    sub = p.add_subparsers(dest="command", metavar="COMMAND")

    list_p = sub.add_parser(
        "list", help="list implemented kernels and communication primitives")
    group = list_p.add_mutually_exclusive_group()
    group.add_argument("--kernels", action="store_true",
                       help="only kernels (src/c/vkernels/kernels)")
    group.add_argument("--comm", action="store_true",
                       help="only communication primitives (src/c/vkernels/comm)")
    list_p.add_argument("--cuda-only", action="store_true",
                        help="only entries with a CUDA implementation")
    list_p.add_argument("--host-only", action="store_true",
                        help="only entries with a host implementation")
    list_p.add_argument("--json", action="store_true",
                        help="machine-readable JSON output")

    info_p = sub.add_parser(
        "info", help="show details for one kernel or primitive")
    info_p.add_argument("name", help="kernel or primitive name")

    tune_p = sub.add_parser(
        "tune", help="persistent launch-config tuning (Triton + native)")
    tune_sub = tune_p.add_subparsers(dest="tune_command", metavar="ACTION")
    tune_sub.add_parser("status", help="what is tuned, both tiers") \
        .add_argument("--json", action="store_true",
                      help="machine-readable JSON output")
    run_p = tune_sub.add_parser(
        "run", help="run the sweep and persist the winners")
    run_p.add_argument("name", nargs="*", help="registry kernel name")
    run_p.add_argument("--all", action="store_true", help="tune every entry")
    clear_p = tune_sub.add_parser(
        "clear", help="delete stored configs (both tiers)")
    clear_p.add_argument("name", nargs="*", help="registry kernel name")
    clear_p.add_argument("--all", action="store_true", help="clear every entry")
    return p


def _truncate(s: str, width: int) -> str:
    if len(s) <= width:
