// vkernels/core/stream.cpp — host implementation of vkernels::Stream.
#include "vkernels/core/stream.hpp"

#include <condition_variable>
#include <deque>
#include <mutex>
#include <thread>

namespace vkernels {

struct Stream::Impl {
  std::deque<std::function<void()>> queue;
  mutable std::mutex m;
  std::condition_variable work_cv;   // signalled when a task is enqueued
  std::condition_variable done_cv;   // signalled when outstanding hits zero
  std::size_t outstanding = 0;
  std::size_t total = 0;
  bool stop = false;
  std::thread worker;

  Impl() : worker([this] { loop(); }) {}

  ~Impl() {
    {
      std::lock_guard<std::mutex> lk(m);
      stop = true;
    }
    work_cv.notify_one();
    if (worker.joinable()) worker.join();
  }

  void loop() {
    for (;;) {
      std::function<void()> task;
      {
        std::unique_lock<std::mutex> lk(m);
        work_cv.wait(lk, [this] { return stop || !queue.empty(); });
        if (stop && queue.empty()) return;
        task = std::move(queue.front());
        queue.pop_front();
      }
      {
        task();  // may acquire/release the GIL via wrapped callables
      }          // task destroyed here, BEFORE the completion signal
      {
        std::lock_guard<std::mutex> lk(m);
        if (--outstanding == 0) done_cv.notify_all();
      }
    }
  }
};

Stream::Stream() : impl_(new Impl()) {}

Stream::~Stream() { delete impl_; }

Stream::Stream(Stream&& other) noexcept : impl_(other.impl_) { other.impl_ = nullptr; }

Stream& Stream::operator=(Stream&& other) noexcept {
  if (this != &other) {
    delete impl_;
    impl_ = other.impl_;
    other.impl_ = nullptr;
  }
  return *this;
}

void Stream::submit(std::function<void()> task) {
  std::lock_guard<std::mutex> lk(impl_->m);
  impl_->queue.push_back(std::move(task));
  ++impl_->outstanding;
  ++impl_->total;
  impl_->work_cv.notify_one();
}

void Stream::wait() {
  std::unique_lock<std::mutex> lk(impl_->m);
  impl_->done_cv.wait(lk, [this] { return impl_->outstanding == 0; });
}

std::size_t Stream::submitted() const { return impl_->total; }

}  // namespace vkernels
// vkernels/comm/overlap.cpp
#include "vkernels/comm/overlap.hpp"

#include <future>
#include <memory>
#include <vector>

namespace vkernels::comm {

OverlapExecutor::Result OverlapExecutor::run(std::size_t iters,
                                             std::function<int(std::size_t)> compute,
                                             std::function<void(std::size_t, int)> comm) {
  std::vector<std::shared_future<int>> ready;
  ready.resize(iters);

  for (std::size_t i = 0; i < iters; ++i) {
    auto promise = std::make_shared<std::promise<int>>();
    ready[i] = promise->get_future().share();

    // Submit compute(i) on the compute stream; it fulfils the promise.
    // Note: `compute`/`comm` are captured BY REFERENCE. Copying a
    // pybind11-wrapped std::function (func_handle) needs the GIL, and the
    // caller may have released it while we block below; the reference is
    // safe because run() waits for every task before returning.
    compute_.submit([&compute, i, promise]() {
      int v = compute(i);
      promise->set_value(v);
    });

    // Submit comm(i) on the comm stream; it blocks on the future (honouring the
    // data dependency) while the compute stream is free to start compute(i+1).
    auto fut = ready[i];
    comm_.submit([&comm, i, fut]() {
      int v = fut.get();
      comm(i, v);
    });
  }

  compute_.wait();
  comm_.wait();

  return Result{iters, iters};
}

