class Stream:
    """Ordered, asynchronous queue of tasks backed by one worker thread.

    Mirrors the host C++ ``vkernels::Stream``: tasks run in submission
    order; distinct streams run concurrently.
    """

    def __init__(self):
        self._queue: deque = deque()
        self._cv = threading.Condition()
        self._outstanding = 0
        self._total = 0
        self._stop = False
        self._thread = threading.Thread(target=self._loop, daemon=True)
        self._thread.start()

    def _loop(self) -> None:
        while True:
            with self._cv:
                self._cv.wait_for(lambda: self._stop or self._queue)
                if self._stop and not self._queue:
                    return
                task = self._queue.popleft()
            task()
            with self._cv:
                self._outstanding -= 1
                if self._outstanding == 0:
                    self._cv.notify_all()

    def submit(self, task) -> None:
        with self._cv:
            self._queue.append(task)
            self._outstanding += 1
            self._total += 1
            self._cv.notify()

    def wait(self) -> None:
        with self._cv:
            self._cv.wait_for(lambda: self._outstanding == 0)

    def submitted(self) -> int:
        with self._cv:
            return self._total

    def close(self) -> None:
        with self._cv:
            if self._stop:
                return
            self._stop = True
            self._cv.notify()
        self._thread.join()


