#define EXPECT_NE(a, b) VK_COMPARE_(a, b, !=, !=)
#define EXPECT_LT(a, b) VK_COMPARE_(a, b, <, <)
#define EXPECT_LE(a, b) VK_COMPARE_(a, b, <=, <=)
#define EXPECT_GT(a, b) VK_COMPARE_(a, b, >, >)
#define EXPECT_GE(a, b) VK_COMPARE_(a, b, >=, >=)

