"""Backend selection for the vkernels Python bindings.

The public API in :mod:`vkernels.kernels`, :mod:`vkernels.comm` and
:mod:`vkernels.core` is backend-agnostic. Two backends implement it:

* **compiled** — the pybind11 extension :mod:`vkernels._core` (built from
  ``src/python/vkernels/_core.cpp`` by CMake when ``VKERNELS_BUILD_PYTHON=ON``).
  Every call crosses into the C++ library under ``src/c/vkernels/``; this is
  the fast path and the one that exercises the real kernels.
* **fallback** — a pure-Python (numpy) reference in :mod:`vkernels._fallback`
  that mirrors the CPU reference implementations, so the package stays
  importable and testable on machines where the extension was not built
  (mirroring the repository's "CPU reference always works" philosophy).

``load_extension()`` returns the compiled module when it can be found and
``None`` otherwise. Resolution order:

1. an already-importable ``vkernels._core`` (installed wheel copy or
   ``PYTHONPATH`` pointing at a build tree), then
2. a ``_core*.so`` sitting directly next to this file (wheel-installed
   extension that failed step 1 — e.g. ABI mismatch), then
3. a freshly built ``build/*/python/vkernels/_core*.so`` under the
   repository root (dev / editable-install CMake layout), newest first, then
4. ``None`` (the fallback backend is used).
"""

from __future__ import annotations

import importlib
import importlib.util
from pathlib import Path

_PKG_DIR = Path(__file__).resolve().parent

# Failure types a compiled-extension load can legitimately produce: ImportError
# for dlopen/dynamic-module problems (wrong interpreter, undefined symbols,
# missing PyInit), OSError for file-level issues, RuntimeError for in-module
# init checks (pybind11/numpy ABI-mismatch style). Anything else is a loader
# or module-init bug and must propagate instead of degrading to the fallback.
_EXTENSION_LOAD_ERRORS = (ImportError, OSError, RuntimeError)


def _repo_root() -> Path | None:
    """Repository root (a directory containing ``src/c/vkernels``), or None."""
    for candidate in (_PKG_DIR, *_PKG_DIR.parents):
        if (candidate / "src" / "c" / "vkernels").is_dir():
            return candidate
    return None


def _find_next_to_package() -> Path | None:
    """A ``_core*.so`` in the same directory as this file (wheel install)."""
    candidates = sorted(_PKG_DIR.glob("_core*.so"))
    if not candidates:
        return None
    return max(candidates, key=lambda p: p.stat().st_mtime)


def _find_built_extension() -> Path | None:
    """Newest ``build/*/python/vkernels/_core*.so`` under the repo root."""
    root = _repo_root()
    if root is None:
        return None
    candidates = sorted(root.glob("build/*/python/vkernels/_core*.so"))
    if not candidates:
        return None
    return max(candidates, key=lambda p: p.stat().st_mtime)


def _load_from_path(path: Path) -> object | None:
    """Try to load a .so from a filesystem path; return the module or None."""
    try:
        spec = importlib.util.spec_from_file_location("vkernels._core", path)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod
    except _EXTENSION_LOAD_ERRORS:
        return None


_loaded: object | None = None
_tried = False


def load_extension():
    """Import and return the compiled ``vkernels._core`` module, or None.

    The result is cached, so repeated calls are cheap. Failures (missing
    extension, ABI mismatch, numpy unavailable) degrade gracefully to None.
    """
    global _loaded, _tried
    if _tried:
        return _loaded
    _tried = True

    # 1. Already importable (installed wheel, or build dir on PYTHONPATH).
    try:
        _loaded = importlib.import_module("vkernels._core")
        return _loaded
    except _EXTENSION_LOAD_ERRORS:
        pass

    # 2. Next to this file (wheel-installed, but step 1 failed — e.g.
    #    the extension was built for a different Python or glibc).
    path = _find_next_to_package()
    if path is not None:
        _loaded = _load_from_path(path)
        if _loaded is not None:
            return _loaded

    # 3. Built by CMake into build/<preset>/python/vkernels/.
    path = _find_built_extension()
    if path is not None:
        _loaded = _load_from_path(path)
        return _loaded

    # 4. No compiled backend.
    _loaded = None
    return None


def backend_name() -> str:
    """``"compiled"`` when the extension is loaded, else ``"fallback"``."""
    return "compiled" if load_extension() is not None else "fallback"
# Root project file for the vkernels repository, managed with uv.
#
# The Python side (the `vkl` CLI + kernel discovery, under src/python/vkernels/) is
# a src-layout package. `uv sync` installs it (editable) together with its
# dependencies into .venv/; `uv run vkl ...` / `uv run python -m vkernels.cli`
# then work from anywhere in the repository. The C++/CUDA library under
# src/c/ is built separately with CMake (see CMakePresets.json / Makefile) and
# is discovered at runtime by src/python/vkernels/_backend.py.
[build-system]
requires = ["setuptools>=68"]
build-backend = "setuptools.build_meta"

[project]
name = "vkernels-cli"
version = "0.1.0"
description = "vkl — low-level GPU kernels and communication primitives with Python bindings"
readme = "README.md"
requires-python = ">=3.10"
license = "MIT"
authors = [{ name = "opentela-ai" }]
keywords = ["cuda", "kernels", "gpu", "collectives", "allreduce"]
classifiers = [
    "Development Status :: 3 - Alpha",
    "Intended Audience :: Developers",
    "Operating System :: POSIX :: Linux",
    "Programming Language :: Python :: 3",
    "Programming Language :: Python :: 3.9",
    "Programming Language :: Python :: 3.10",
    "Programming Language :: Python :: 3.11",
    "Programming Language :: Python :: 3.12",
    "Topic :: Scientific/Engineering :: Artificial Intelligence",
]
dependencies = [
    "numpy>=1.24",
]

[project.optional-dependencies]
# Compiled backend: the pybind11 extension (*not* shipped in the
# pure-Python wheel; install a platform wheel or build from source).
compiled = []
# CuTe DSL (CUTLASS Python DSL) for the sm_90 fp8 blockwise grouped-GEMM
# path (torch_ops/glm_fp8_blockwise_gemm.py). Optional: without it the
# module falls back to its pure-torch reference path (the oracle).
cute = ["nvidia-cutlass-dsl>=4.7", "cuda-python>=13"]
# Megakernel model compiler (src/python/vkernels/compiler/ — capture →
# operator IR → schedule → Triton/CuTe codegen, with the GPT-2/dense-Qwen3
# model definitions). Needs torch + triton (+ safetensors for the hybrid
# path's checkpoint-shard loading); without them the subpackage is
# simply not imported (the floe repo consumes it via vkernels-cli[compiler]).
compiler = ["torch", "triton", "safetensors"]

[project.scripts]
vkl = "vkernels.cli.main:main"

[dependency-groups]
dev = [
    "pytest>=8",
    "build>=1.0",
    "twine>=5.0",
    # Checkpoint-shard loading for the megakernel feasibility tests
    # (tests/python/test_megakernel_27b.py) and the compiler's hybrid
    # checkpoint path (device_triton_hybrid).
    "safetensors>=0.4",
]

# src-layout: the `vkernels` package lives under src/python/.
# When building a platform wheel (meta/scripts/build_wheel.sh copies the
# compiled _core*.so here before `python -m build`), setuptools includes
# it automatically; the fallback backend is used when no .so is present.
[tool.setuptools.packages.find]
where = ["src/python"]

# Include the compiled pybind11 extension in the wheel when it exists.
# The build script (meta/scripts/build_wheel.sh) places the .so here
# temporarily; pip-installing the resulting wheel places it alongside
# the .py files so `import vkernels._core` works at runtime.
[tool.setuptools.package-data]
vkernels = ["_core*.so"]

# setuptools needs this flag to actually include package-data files
# that aren't tracked by a VCS (our temporary .so definitely isn't).
[tool.setuptools]
