    let ptrs = to_ptrs(src_ptrs);
    let mut out: *mut sys::vk_staged_run_1d = std::ptr::null_mut();
    let mut count = 0usize;
    from_status(unsafe {
        sys::vk_stage_runs_1d(
            dst.as_ptr(),
            dst.len(),
            ptrs.as_ptr(),
            dst_offsets.as_ptr(),
            lengths.as_ptr(),
            src_ptrs.len(),
            &mut out,
            &mut count,
        )
    })?;
    let runs = unsafe { std::slice::from_raw_parts(out, count) };
    let result = runs
        .iter()
        .map(|r| StagedRun1D {
            src: r.src as usize,
            dst_offset: r.dst_offset,
            length: r.length,
