def _dequant(w_fp8, scale):
    """128x128 block dequant to fp32 (scale rows: [out_blocks, in_blocks])."""
    N, K = w_fp8.shape
    s = scale.float()
    blocks = s.repeat_interleave(128, 0).repeat_interleave(128, 1)[:N, :K]
    return w_fp8.float() * blocks


