using vkernels::kernels::gemm;

TEST(Gemm, IdentityAlphaOneBetaZero) {
  // 2x2 * 2x2 identity
  std::vector<float> A = {1, 2, 3, 4};          // row-major [[1,2],[3,4]]
  std::vector<float> B = {1, 0, 0, 1};          // identity
  std::vector<float> C(4, 0.0f);
