    def new_storage(self, name: str, numel: int) -> int:
        sid = self._next_storage
        self._next_storage += 1
        self.storage_sizes[sid] = numel
        self.storage_names[sid] = name
        self.storage_versions[sid] = 0
        self.fresh_storages.add(sid)
        return sid

    def add_external_storage(self, sid: int, name: str, numel: int) -> None:
        """Register caller-owned storage (weights, cache, inputs)."""
        self.storage_sizes.setdefault(sid, numel)
        self.storage_names.setdefault(sid, name)
        self.storage_versions.setdefault(sid, 0)

    def add_tensor(
        self,
        name: str,
        shape: Sequence[int],
        dtype: DType,
        *,
        storage_id: int,
        strides: Sequence[int],
        offset: int = 0,
        valid_length: Optional[ValidLength] = None,
    ) -> TensorValue:
        if name in self.tensors:
            raise ValueError(f"duplicate tensor name {name!r}")
        if any(s < 0 for s in strides):
            raise ValueError(f"negative strides are unsupported (tensor {name!r})")
        vid = self._next_vid
        self._next_vid += 1
        tv = TensorValue(vid, name, shape, dtype, strides, storage_id, offset, valid_length)
        self.tensors[name] = tv
        return tv

    def record(
        self,
        kind: str,
        *,
        inputs: Sequence[str],
        outputs: Sequence[str],
        attributes: dict,
        reads: Sequence[Region],
        writes: Sequence[Region],
        source_location: str,
        numerical_contract: Optional[dict] = None,
    ) -> Operator:
        op = Operator(
            opid=self._next_opid,
            kind=kind,
            inputs=tuple(inputs),
            outputs=tuple(outputs),
            attributes=dict(attributes),
            read_regions=tuple(reads),
            write_regions=tuple(writes),
            source_location=source_location,
            numerical_contract=dict(numerical_contract or {}),
        )
        self._next_opid += 1
    def _record(
        self,
        kind: str,
        *,
        inputs: Sequence[SymbolicTensor | str],
        outputs: Sequence[SymbolicTensor],
        attributes: dict,
        reads: Sequence[Region],
        writes: Sequence[Region],
        source_location: str = "",
        numerical_contract: Optional[dict] = None,
    ):
        if kind not in ARITHMETIC_OP_KINDS:
            raise UnsupportedOperator(
                f"operator kind {kind!r} is outside the supported subset",
                node=source_location or kind,
                missing_contract="a device-callable task lowering with modeled memory effects",
            )
        self._op_counter += 1
        loc = source_location or f"op#{self._op_counter} {kind}"
        input_names = tuple(x.value.name if isinstance(x, SymbolicTensor) else str(x) for x in inputs)
        output_names = tuple(o.value.name for o in outputs)
        return self.graph.record(
            kind,
            inputs=input_names,
            outputs=output_names,
            attributes=attributes,
            reads=reads,
            writes=writes,
            source_location=loc,
            numerical_contract=numerical_contract,
        )

