    for (int h = 0; h < H; ++h) {
      std::fill(state.begin(), state.end(), 0.0f);
      const size_t bh = (size_t)(b * H + h) * S;
      for (int t = 0; t < S; ++t) {
        const float* kt = k + (bh + t) * D;
        const float* vt = v + (bh + t) * D;
        const float* qt = q + (bh + t) * D;
        const float gt = g[bh + t];        // scalar gate [B,H,S]
